import math
import pool_table
from IPython.display import display, HTML
import traceback
from collections.abc import Iterable

def test_equal(x, y):
     if isinstance(x, float) and isinstance(y, float):
         if math.isnan(x):
             return math.isnan(y)
         return math.isclose(x, y, rel_tol=1e-07, abs_tol=1e-15)
     elif isinstance(x, dict) and isinstance(y, dict):
         if x.keys() != y.keys():
             return False
         return all(test_equal(x[k], y[k]) for k in x)
     elif isinstance(x, Iterable) and not isinstance(x, (str, bytes)) and \
         isinstance(y, Iterable) and not isinstance(y, (str, bytes)):
         if len(x) != len(y):
            return False
         return all(test_equal(a, b) for a, b in zip(x, y))
     elif hasattr(x, '__dict__') and hasattr(y, '__dict__'):
          return test_equal(vars(x), vars(y))
     else:
          return x == y

