def show_failed_test(setup, function, args):
    print('\u274C Test Failed:')
    print()     
    if setup:
        for input in setup.split(';'):
            print(input.replace(':', ' = '))
        print()
    print(f'{function.__name__}({args.rstrip(",")})')
    print()    

def run_tests(function, Ball=None, Cushion=None, explain=True):
    if explain:
        print()
    count = 0
    if function.__name__ in tests:
        for setup, args_str, expected_result in tests[function.__name__]:
            if setup:
                src = setup.replace(':', ' = ')
                exec(src)
            args = eval(args_str)
            try:
                if isinstance(args, tuple):
                    actual_result = function(*args)
                else:
                    actual_result = function(args)
            except Exception as e:
                if explain:
                    show_failed_test(setup, function, args_str)
                    print('Crashed with runtime exception:')
                    traceback.print_exc()
                return False

            if ':' in expected_result:
                # Returns None, instead modifies its input parameters
                if actual_result != None:
                    if explain:
                        show_failed_test(setup, function, args_str)
                        print(f'Expected result: None')
                        print(f'Actual result: {actual_result}')
                        print('This function is meant to update the attributes of the ball object, not return a value')
                    return False
                    
                for part in expected_result.split(';'):
                    name,expect = part.split(':')
                    actual = eval(name)
                    expected = eval(expect)
                    if not test_equal(actual, expected):
                        if explain:
                            show_failed_test(setup, function, args_str)
                            print(f'{name} is expected to be: {expected}')
                            print(f'But {name} is actually  : {actual}')
                        return False
            else:
                # Normal result, doesn't modify its input parameters
                if not test_equal(actual_result, eval(expected_result)):
                    if explain:
                        show_failed_test(setup, function, args_str)
                        print(f'Expected result: {expected_result}')
                        print(f'Actual result: {actual_result}')
                    return False
                
                if setup:
                    for input in setup.split(';'):
                        parts = input.split(':')
                        expected = eval(parts[1])
                        actual = eval(parts[0])
                        if not test_equal(actual, expected):
                            if explain:
                                show_failed_test(setup, function, args_str)
                                print(f'Input parameter {parts[0]} should not be modified')
                                print(f'It should remain as: {expected}')
                                print(f'But has changed to : {actual}')
                            return False
            count += 1

    if explain:
        print(f'\u2705 Passed all ({count}) tests, well done!')            
    return True
